CREATE OR REPLACE PACKAGE compteur IS
  nb_appels NUMBER := 0;
  PROCEDURE incrementer;
END compteur;
/

CREATE OR REPLACE PACKAGE BODY compteur IS
  PROCEDURE incrementer IS
  BEGIN
    nb_appels := nb_appels + 1;
  END incrementer;
END compteur;
